function chip(x, y, w, name, left, right, sub){
  const n = Math.max(left.length, right.length), h = 24 + n*16;
  let s = `<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="4" fill="var(--panel2)" stroke="var(--ink)"/><text x="${x+w/2}" y="${y-6}" text-anchor="middle" font-size="12" font-weight="700" fill="var(--ink)">${name}</text>${sub?`<text x="${x+w/2}" y="${y+h+14}" text-anchor="middle" font-size="10" fill="var(--ink2)">${sub}</text>`:''}`;
  left.forEach(([p,nm,to],i) => { const yy = y + 20 + i*16; s += `<line x1="${x-34}" y1="${yy}" x2="${x}" y2="${yy}" stroke="var(--ink2)"/><text x="${x+4}" y="${yy+4}" font-size="10" fill="var(--ink)" font-family="monospace">${p}</text><text x="${x-38}" y="${yy+4}" font-size="10" fill="var(--accent2)" text-anchor="end">${nm}${to?' — '+to:''}</text>`; });
  right.forEach(([p,nm,to],i) => { const yy = y + 20 + i*16; s += `<line x1="${x+w}" y1="${yy}" x2="${x+w+34}" y2="${yy}" stroke="var(--ink2)"/><text x="${x+w-4}" y="${yy+4}" font-size="10" fill="var(--ink)" text-anchor="end" font-family="monospace">${p}</text><text x="${x+w+38}" y="${yy+4}" font-size="10" fill="var(--accent2)">${nm}${to?' — '+to:''}</text>`; });
  return s;
}
